module tomb_raider (\n    input clk,\n    input rst_n,\n    input start,\n    input [7:0] grid [0:7][0:7],  // 8x8 grid\n    input [3:0] gargoyle_mask,\n    output reg [3:0] min_rotations,\n    output reg done,\n    output reg valid\n);\n\n// State declarations\nlocalparam [3:0] IDLE             = 4'd0;\nlocalparam [3:0] SETUP            = 4'd1;\nlocalparam [3:0] SIMULATE_BEAM    = 4'd2;\nlocalparam [3:0] CHECK_CONNECTIONS= 4'd3;\nlocalparam [3:0] UPDATE_ROTATION  = 4'd4;\nlocalparam [3:0] FINALIZE         = 4'd5;\n\n// Constants\nlocalparam MAX_GARGOYLES = 4;\nlocalparam GRID_SIZE = 8;\n\n// Internal registers\nreg [3:0] state;\nreg [3:0] next_state;\nreg [5:0] current_cell;   // 6-bit for 64 cells (0-63)\nreg [2:0] gargoyle_index;\nreg [1:0] beam_dir;\nreg [7:0] beam_x, beam_y;\nreg [3:0] rot_count;\nreg [3:0] best_rot;\nreg [3:0] gargoyle_count;\nreg [15:0] connection_mask;\nreg [7:0] visited;\n\n// Gargoyle storage (packed)\nreg [2:0] gx [0:3];  // X positions\nreg [2:0] gy [0:3];  // Y positions\nreg [0:3] gt;         // Types (0=V,1=H)\n\n// Simulation control\nreg beam_active;\nreg [5:0] sim_step;\n\n// Cell type parameters\nlocalparam [7:0] EMPTY           = 8'd0;\nlocalparam [7:0] OBSTACLE        = 8'd1;\nlocalparam [7:0] MIRROR_SLASH    = 8'd2;\nlocalparam [7:0] MIRROR_BACKSLASH= 8'd3;\nlocalparam [7:0] GARGOYLE_V      = 8'd4;\nlocalparam [7:0] GARGOYLE_H      = 8'd5;\n\ninteger i;  // Loop variable\n\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        // Reset all registers\n        state <= IDLE;\n        done <= 1'b0;\n        valid <= 1'b0;\n        min_rotations <= 4'hF;\n        gargoyle_count <= 4'd0;\n        current_cell <= 6'd0;\n        gargoyle_index <= 3'd0;\n        rot_count <= 4'd0;\n        best_rot <= 4'hF;\n        connection_mask <= 16'd0;\n        beam_active <= 1'b0;\n        sim_step <= 6'd0;\n\n        // Initialize gargoyle arrays\n        for (i = 0; i < 4; i = i + 1) begin\n            gx[i] <= 3'd0;\n            gy[i] <= 3'd0;\n        end\n        gt <= 4'd0;\n    end else begin\n        case (state)\n            IDLE: begin\n                done <= 1'b0;\n                valid <= 1'b0;\n                if (start) begin\n                    state <= SETUP;\n                    current_cell <= 6'd0;\n                    gargoyle_count <= 4'd0;\n                end\n            end\n\n            SETUP: begin\n                if (current_cell < 6'd63) begin\n                    current_cell <= current_cell + 1;\n                    \n                    // Detect gargoyles\n                    if (grid[current_cell[5:3]][current_cell[2:0]] == GARGOYLE_V ||\n                        grid[current_cell[5:3]][current_cell[2:0]] == GARGOYLE_H) begin\n                        if (gargoyle_count < 4) begin\n                            gx[gargoyle_count] <= current_cell[5:3];\n                            gy[gargoyle_count] <= current_cell[2:0];\n                            gt[gargoyle_count] <= (grid[current_cell[5:3]][current_cell[2:0]] == GARGOYLE_H);\n                            gargoyle_count <= gargoyle_count + 1;\n                        end\n                    end\n                end else begin\n                    state <= (gargoyle_count == 0) ? FINALIZE : SIMULATE_BEAM;\n                    gargoyle_index <= 3'd0;\n                    rot_count <= 4'd0;\n                end\n            end\n\n            SIMULATE_BEAM: begin\n                // [Beam simulation logic goes here]\n                // Simplified for brevity - keep state transitions\n                state <= CHECK_CONNECTIONS;\n            end\n\n            CHECK_CONNECTIONS: begin\n                // [Connection checking logic]\n                state <= UPDATE_ROTATION;\n            end\n\n            UPDATE_ROTATION: begin\n                if (rot_count < (1 << gargoyle_count)) begin\n                    rot_count <= rot_count + 1;\n                    state <= SIMULATE_BEAM;\n                end else begin\n                    state <= FINALIZE;\n                end\n            end\n\n            FINALIZE: begin\n                done <= 1'b1;\n                valid <= (best_rot != 4'hF);\n                min_rotations <= best_rot;\n                state <= IDLE;  // Return to idle\n            end\n\n            default: state <= IDLE;\n        endcase\n    end\nend\n\nendmodule